   "desc": "སྐད་གཉིས་ཡིག་འבྲུར་ལ་རྣམ་པ་གཉིས་ཡོད་དེ་: ཡིག་འבྲུར་གཅིག་གི་ནང་དུ་ཕྲེང་གཉིས་ཡོད་པའམ་ཡང་ན་དུས་ཐིག་གཅིག་པོའི་སྟེང་དུ་ཡིག་འבྲུར་གཉིས་ཡོད་པའོ། དགེ་སྐྱོན་དང་། དེ་དག་གི་བར་དུ་ཇི་ལྟར་བརྗེ་སྤོར་བྱེད་དགོས་ཚུལ། – AI-SRTSub",
