     "17 ཁྲིམས་སྲོལ་གྱིས་རིམ་པ་གསུམ་གྱི་ཐོག་ནས་གསར་རྙེད་རྣམས་སྙན་ཞུ་བྱེད་དེ་: **ནོར་འཁྲུལ** (ཡིག་འབྲུར་བརླགས་པ། དུས་རྟགས་རྣམ། འགོ་ཚུགས་པ་ལས་མཇུག་བསྡོམས་པ་སྔ་བ། ཨང་གྲངས་ཆག་པ)། **ཉེན་བརﺪ** (སྟོང་པའི་ནང་འཇུག ཁེབས་ཟློག གནས་ཡུན་ཐུང་དྲགས་པའམ་རིང་དྲགས་པ། ཀློག་མྱུར་ཚད་ཚད་བརྒལ་བ། ཕྲེང་ཧ་ཅང་ཞེང་ཆེ་བ། ཕྲེང་གཉིས་ལས་བརྒལ་བ)། དེ་བཞིན་ **དྲན་སྐུལ** (ཕྲེང་ཆད་གནས་ཡུལ། མགོ་མཇུག་གི་སྟོང་ཆ། སྟོང་ཆ་ཆད་པ། ཚེག་བར་གྱི་ཚད་གཞི། སོགས་སོ) བཅས་སོ། གསར་རྙེད་རེ་རེར་ནང་འཇུག་ཨང་གྲངས་དང་ \"ཚད་འཇལ་ X, ཚད་གཞི་ Y\" ཞེས་པའི་ཞིབ་ཕྲ་ཡོད་པ་དང་། ཐོ་གཞི་དེ་རིམ་པ་ལྟར་འཚག་བསྲེས་བྱེད་ཆོག སྐད་གཉིས་ནང་འཇུག་ལ་དམིགས་བསལ་ཆོག་མཆན་ཡོད་དེ་: རྣམ་པ་གཉིས་ཀ་རང་འགུལ་ངོས་འཛིན་བྱེད་པ་དང་། ཁེབས་ཟློག་ཞིབ་བཤེར་གྱིས་ཟུང་ཡོངས་ལ་ཆོག་མཆན་སྤྲོད་པ། ཀློག་མྱུར་ཚད་ཀྱིས་དམིགས་ཡུལ་སྐད་ཡིག་ནང་བྲིས་པའི་ཕྲེང་ཁོ་ན་རྩིས་ཀྱི་ཡོད།"
