   "desc": "SRT བརྙན་ཞོལ་དེ་ 1920×1080 བརྙན་ཡོལ་དང་གཙང་ཞིང་ཚད་ལྡན་གྱི་བཟོ་བཀོད་དང་ལྡན་པའི་ ASS (Advanced SubStation Alpha) རུ་བསྒྱུར་ནས་རྩེད་ཆས་གང་དུའང་ཐད་ཀར་སྤྱོད་ཆོག བཤར་ཆས་ནང་དུ་ལས་ཀ་བྱེད་ཀྱི་ཡོད།",
   "h1": "SRT ནས་ ASS བརྗེས་པ།",
   "intro": "SRT བརྙན་ཞོལ་དེ་ ASS རུ་བསྒྱུར་བ། ཡིག་ཆ་འཐེན་ནས་ནང་དུ་འཇོག་པ། ASS གདམས་ནས་ཕབ་ལེན། 1920×1080 བརྙན་ཡོལ་དང་ཚད་ལྡན་གྱི་བཟོ་བཀོད་རང་འགུལ་གྱིས་བཟོ་ཡི་ཡོད།",
