     "ཀློག་མགྱོགས་ནི་ ལྟད་མོ་པས་བརྙན་ཞོལ་དེ་བརྙན་ཡོལ་དུ་གནས་པའི་དུས་ཡུན་ནང་ཚར་བར་ཀློག་ཐུབ་མین«»ཡིན། སྤྱི་འགྲོས་ནི་སླ་སྟེ། ཡིག་དོན་ཡངས་ཚད་དེ་བརྙན་ཡོལ་གྱི་དུས་ཡུན་གྱིས་བགོད་པའོ། ལས་རིགས་ཀྱི་ཚད་གཞི། རྒྱ་ཡིག འཇར་པན་ཡིག་དང་ კორეული ཡིག་ལ་སྐར་ཆར་ཡིག་འབྲུ་ཆེ་བའི་ཚད་ 9 (ཕྱེད་ཡིག་འབྲུ་ 18), སྐད་རིགས་གཞན་ལ་སྐར་ཆར་ཕྱེད་ཡིག་འབྲུ་ 20 ཡིན། སྐར་ཆ་ 1 ཡི་དུས་ཡུན་ཡོད་པའི་ཡིག་འབྲུ་ 20 ཅན་གྱི་ཕྲེང་ཞིག་གི་སྐར་ཆར་ཡིག་འབྲུ་ 40 ཡིན་པས་ཚད་གཞི་ལས་ལྡོག་གཉིས་ལྷག་ཡོད་པས་ལྟད་མོ་པས་ནམ་ཡང་ཀློག་མི་ཐུབ།"
